import { useState } from "react";
import axios from "axios";
import { FaPaperPlane, FaTrash } from "react-icons/fa"; // Import icons

function App() {
  const [input, setInput] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim()) return; // Prevent empty input
    setLoading(true);
    setResponse(""); // Clear previous response
    try {
      const res = await axios.post("http://localhost:5000/chat", {
        prompt: input,
      });
      setResponse(res.data.response.parts[0].text);
    } catch (error) {
      console.error("Error:", error);
      setResponse("Error fetching response. Check console.");
    }
    setLoading(false);
  };

  const handleClear = () => {
    setInput("");
    setResponse("");
  };

  return (
    <div className="app-container">
      <h2>🤖 AI Tutor</h2>
      <textarea
        rows="4"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Ask me anything..."
      />
      <br />
      <button onClick={handleSend} disabled={loading}>
        {loading ? "Thinking..." : <><FaPaperPlane /> Ask AI</>}
      </button>
      <button onClick={handleClear} style={{ background: "#dc3545", marginLeft: "10px" }}>
        <FaTrash /> Clear
      </button>

      {response && (
        <div className="response-container">
          <h3>📢 AI Response:</h3>
          <p>{response}</p>
        </div>
      )}
    </div>
  );
}

export default App;
